import { Component, signal } from '@angular/core';

type Status = 'pending' | 'shipped' | 'cancelled';

@Component({
  selector: 'app-order-status',
  template: `
    @if (status() === 'shipped') {
      <p>Your order is on its way.</p>
    } @else if (status() === 'cancelled') {
      <p>This order was cancelled.</p>
    } @else {
      <p>We are preparing your order.</p>
    }
    <button (click)="ship()">Mark as shipped</button>
  `,
})
export class OrderStatus {
  readonly status = signal<Status>('pending');

  ship(): void {
    this.status.set('shipped');
  }
}

@if (currentUser(); as user) {
  <h2>{{ user.name }}</h2>
  <p>{{ user.email }}</p>
} @else {
  <p>Not signed in.</p>
}

import { Component, signal } from '@angular/core';

interface Task {
  id: number;
  title: string;
  done: boolean;
}

@Component({
  selector: 'app-task-list',
  template: `
    <ul>
      @for (task of tasks(); track task.id; let i = $index, last = $last) {
        <li>
          {{ i + 1 }}. {{ task.title }}
          @if (task.done) { (done) }
          @if (last) { - last one }
        </li>
      } @empty {
        <li>Nothing to do.</li>
      }
    </ul>
    <p>{{ tasks().length }} tasks</p>
  `,
})
export class TaskList {
  readonly tasks = signal<Task[]>([
    { id: 1, title: 'Write the lesson', done: true },
    { id: 2, title: 'Review the examples', done: false },
    { id: 3, title: 'Publish', done: false },
  ]);
}

@switch (role()) {
  @case ('admin') { <p>You can edit everything.</p> }
  @case ('editor') { <p>You can edit your own posts.</p> }
  @default { <p>You can read posts.</p> }
}

@let total = subtotal() + shipping();
<p>Subtotal: {{ subtotal() }}</p>
<p>Shipping: {{ shipping() }}</p>
<p>Total: {{ total }}</p>
@if (total > 100) {
  <p>You qualify for free returns.</p>
}
